def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    threat_scores = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        opp_budget = opp.get('budget', 0)
        opp_hp = opp.get('hp', 0)
        opp_nwd = opp.get('no_water_days', 0)
        score = 0.0
        score += min(float(opp_budget) / 100.0, 2.0)
        score += float(max(0, opp_hp - 2)) * 0.15
        score += float(max(0, 2 - opp_nwd)) * 0.2
        if bid is not None:
            score += min(float(bid) / 80.0, 2.0)
        threat_scores.append(score)

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_threat = max(threat_scores) if threat_scores else 0.0

    supply_pressure = (MAX_SUPPLY - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgent = hp <= 2 or no_water_days >= 1
    fragile = hp <= 4

    if urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev_bid + 3.0)
        if supply <= 17:
            target = max(target, DAILY_SALARY * 1.1)
        return float(min(budget, target))

    base = DAILY_SALARY * (0.28 + 0.32 * supply_pressure)

    if highest_prev_bid >= 120:
        if hp >= 6 and no_water_days == 0 and supply >= 20:
            return float(min(budget, DAILY_SALARY * 0.18))
        base = max(base, DAILY_SALARY * 0.72)
    elif highest_prev_bid >= 70:
        base = max(base, min(highest_prev_bid + 2.0, DAILY_SALARY * 0.92))
    elif highest_prev_bid > 0:
        base = max(base, avg_prev_bid + 1.5)
    else:
        base = max(base, DAILY_SALARY * 0.35)

    if max_threat > 2.8:
        base += 6.0
    elif max_threat < 1.2:
        base -= 4.0

    if supply >= 23 and hp >= 6:
        base *= 0.72
    elif supply <= 17:
        base *= 1.18

    if fragile:
        base *= 1.15

    if day >= 8 and hp >= 5:
        base *= 0.9

    reserve_floor = DAILY_SALARY * 0.15
    bid = max(reserve_floor, base)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Basic alive set
    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((k, o))

    if not alive_opps:
        # No competition: bid low but not zero
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If we have no trace bids, use a conservative baseline
    if not yesterday_bids:
        base = DAILY_SALARY * 0.45
        if my_hp <= 2:
            base = DAILY_SALARY * 0.85
        return max(0.0, min(my_budget, base))

    highest_prev_bid = max(yesterday_bids)

    # Supply pressure heuristic: tighter supply -> slightly higher bid
    # Use integer indices safely; here we just map supply to a multiplier.
    # supply in [15,25], WATER_REQ=9 => about 1 or 2 units possible.
    units_possible = int(supply / float(WATER_REQ))  # e.g., 15/9=1.66 -> 1
    if units_possible <= 1:
        supply_mult = 1.10
    else:
        supply_mult = 0.95

    # If someone previously bid extremely high, they likely tried to secure water aggressively.
    # Counter with a moderate bid to avoid burning budget.
    if highest_prev_bid >= DAILY_SALARY * 1.10:
        # Cindy bid big and survived; don't mirror fully.
        if my_hp <= 2:
            bid = DAILY_SALARY * 0.75
        else:
            bid = DAILY_SALARY * 0.55
    elif highest_prev_bid >= DAILY_SALARY * 0.75:
        # Medium pressure
        if my_hp <= 2:
            bid = DAILY_SALARY * 0.65
        else:
            bid = DAILY_SALARY * 0.48
    else:
        # Low pressure: keep budget
        if my_hp <= 2:
            bid = DAILY_SALARY * 0.80
        else:
            bid = DAILY_SALARY * 0.40

    bid *= supply_mult

    # Ensure we never bid more than we can afford
    bid = max(0.0, min(my_budget, bid))

    # If budget is very low, still bid something small to avoid starvation
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        if day_context['supply'] >= WATER_REQ:
            return min(my_status['budget'], DAILY_SALARY * 0.1)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.05)

    current_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 1:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 3:
        current_bid = DAILY_SALARY * 0.75
    elif my_status['hp'] <= 5:
        current_bid = DAILY_SALARY * 0.6

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3:
                current_bid = max(current_bid, highest_prev_bid + 5.0)
            else:
                current_bid = max(current_bid, highest_prev_bid * 0.9)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            current_bid = max(current_bid, average_prev_bid + 2.0)
        else:
            if my_status['hp'] > 5 and day_context['supply'] > WATER_REQ * num_alive_opponents:
                current_bid = min(current_bid, highest_prev_bid + 1.0)
            else:
                current_bid = max(current_bid, DAILY_SALARY * 0.3)

    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    if day_context['supply'] < total_water_needed * 0.8:
        current_bid *= 1.15
    elif day_context['supply'] > total_water_needed * 1.2:
        current_bid *= 0.9

    if day_context['day'] >= EPISODE_DAYS * 0.7:
        current_bid *= 1.1

    final_bid = max(1.0, current_bid)
    final_bid = min(final_bid, my_status['budget'])

    return final_bid
